export const everydayStories=[
 {id:'leaf',title:'Vì sao chiếc lá đổi màu?',tag:'SẮC TỐ · LỚP 7 / 11',art:'leaf',grade:7,lesson:'g7-photosynthesis',intro:'Một chiếc lá vàng không chỉ là chiếc lá được “tô lại”. Màu nhìn thấy phụ thuộc loại sắc tố và lượng tương đối của chúng.',points:['Diệp lục góp phần tạo màu xanh và tham gia quang hợp.','Ở nhiều cây rụng lá theo mùa, khi diệp lục giảm, sắc tố vàng/cam có thể trở nên rõ hơn; sắc tố đỏ có thể được tạo thêm.','Không phải mọi lá đổi màu vì cùng một nguyên nhân; loài, tuổi lá và môi trường đều cần được xem xét.'],question:'Hãy giảm mức diệp lục trong minh họa. Màu khác xuất hiện có chứng minh lá vừa được thêm màu vàng không?',source:['National Park Service · Leaf colour','https://www.nps.gov/articles/why-do-leaves-change-in-the-fall.htm'],control:'Mức diệp lục quy ước',link:'lab'},
 {id:'osmosis',title:'Một lát rau trong nước muối',tag:'THẨM THẤU · LỚP 10',art:'cell',grade:10,lesson:'membrane',intro:'Cùng một mô thực vật, nhưng môi trường bên ngoài khác đi có thể làm dòng nước thuần đổi hướng.',points:['Màng sinh chất cho nước trao đổi; hướng di chuyển thuần liên quan chênh lệch thế nước.','Nếu dung dịch ngoài ưu trương so với tế bào trong mô hình, nước có xu hướng đi ra; khối nguyên sinh co lại.','Quan sát này không chứng minh việc ngâm nước muối khử được mọi vi sinh vật.'],question:'Giữ mốc bên trong ở 50, đổi bên ngoài. Thành tế bào và khối nguyên sinh có thay đổi giống nhau không?',source:['SGK Sinh học 10 · NXBGDVN','https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/sach.4492290247.4492290247'],control:'Chất tan bên ngoài · quy ước',link:'lab'},
 {id:'sweat',title:'Mồ hôi làm mát bằng cách nào?',tag:'ĐIỀU HÒA THÂN NHIỆT · LỚP 8 / 11',art:'water',grade:8,lesson:'g8-temperature',intro:'Da ướt và da được làm mát không phải hai khái niệm đồng nhất. Hãy nhìn vào quá trình bay hơi.',points:['Cơ thể điều hòa thân nhiệt bằng nhiều cơ chế, gồm tiết mồ hôi và thay đổi trao đổi nhiệt qua da.','Khi mồ hôi bay hơi, quá trình này nhận nhiệt và góp phần làm mát.','Độ ẩm không khí cao có thể hạn chế bay hơi; còn tốc độ gió, quần áo và nhiều yếu tố khác chưa có trong sơ đồ.'],question:'Tăng độ ẩm không khí trong minh họa. Vì sao da nhiều mồ hôi không bảo đảm bay hơi hiệu quả?',source:['SGK Khoa học tự nhiên 8 · NXBGDVN','https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/sach.4492018196.4492018196'],control:'Độ ẩm không khí · minh họa',link:'lab'},
 {id:'fruit',title:'Một quả táo bên cạnh nải chuối',tag:'HORMONE THỰC VẬT · LỚP 11',art:'fruit',grade:11,lesson:'growth',intro:'Nhiều loại quả có liên quan tới ethylene trong quá trình chín. Quan sát cần phân biệt tác động hormone với các điều kiện bảo quản khác.',points:['Ethylene là hormone thực vật ở dạng khí, tham gia điều hòa nhiều quá trình, gồm chín quả ở các nhóm phù hợp.','Quả đang chín có thể phát thải ethylene, ảnh hưởng những quả nhạy cảm ở gần.','Mức phản ứng phụ thuộc loại quả, độ chín, nhiệt độ và thông khí; sơ đồ không dự báo số ngày bảo quản.'],question:'So sánh hai tình huống minh họa, rồi kể những điều kiện cần giữ giống nhau nếu muốn quan sát thật.',source:['SGK Sinh học 11 · NXBGDVN','https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/shs-sinh-hoc.4492265451'],extraSource:['OpenStax · Ethylene','https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses'],control:'Giai đoạn chín · không quy đổi ngày',link:'lab'},
 {id:'muscle',title:'Đau cơ hôm sau, vì sao?',tag:'VẬN ĐỘNG · LỚP 8 / 11',art:'muscle',grade:8,lesson:'g8-breathing',intro:'Cảm giác mỏi lúc vận động và đau cơ xuất hiện muộn là những hiện tượng cần phân biệt.',points:['Đau cơ khởi phát muộn có thể xảy ra sau hoạt động mới hoặc tải vận động chưa quen.','Cơ chế thường được liên hệ với tổn thương vi thể và đáp ứng của mô; không nên quy toàn bộ đau cơ hôm sau cho lactate còn tích tụ.','Bài học chỉ so sánh khái niệm, không đánh giá nguyên nhân đau hoặc tình trạng sức khỏe của người xem.'],question:'Chọn một mốc quan sát rồi phân biệt cảm giác xảy ra ngay với cảm giác xuất hiện muộn. Dữ liệu nào còn thiếu để giải thích?',source:['ACSM · Co cơ lệch tâm và tổn thương cơ','https://acsm.org/eccentric-contractions-muscle-damage/'],extraSource:['NCBI PMC · Tổng quan cơ chế DOMS','https://pmc.ncbi.nlm.nih.gov/articles/PMC10716961/'],control:'Dòng thời gian khái niệm · không phải phép đo',link:'lab'}
];
